INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22701, 'តើសមីការស្ដង់ដានៃអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ \(O(0, 0)\) និងអ័ក្សទទឹងស្ថិតនៅលើអ័ក្សអាប់ស៊ីសគឺជាមួយណា?', NULL, '["\\(\\frac{x^2}{a^2} - \\frac{y^2}{b^2} = 1\\)", "\\(\\frac{x^2}{a^2} + \\frac{y^2}{b^2} = 1\\)", "\\(y^2 = 4ax\\)", "\\(\\frac{y^2}{a^2} - \\frac{x^2}{b^2} = 1\\)"]', 0, NULL, 1, 'mcq', 'អ៊ីពែបូលមានផ្ចិត \((0, 0)\) និងអ័ក្សទទឹងលើអ័ក្សអាប់ស៊ីស មានសមីការស្ដង់ដា \(\frac{x^2}{a^2} - \frac{y^2}{b^2} = 1\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22702, 'អ៊ីពែបូលមួយមានកំពូល \(V_1(5, 0)\) និង \(V_2(-5, 0)\) ។ ចំពោះគ្រប់ចំណុច \(P\) នៅលើអ៊ីពែបូល តើ \(|PF_1 - PF_2|\) ស្មើប៉ុន្មាន?', NULL, '["\\(25\\)", "\\(10\\)", "\\(2.5\\)", "\\(5\\)"]', 1, NULL, 1, 'mcq', 'តាមនិយមន័យ \(|PF_1 - PF_2| = V_1V_2 = 2a = 2 \times 5 = 10\) ។', 'និយមន័យអ៊ីពែបូល', 'easy', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22703, 'តើផ្ចិតនៃអ៊ីពែបូល \(\frac{(x - 3)^2}{4} - \frac{(y + 2)^2}{9} = 1\) មានកូអរដោនេប៉ុន្មាន?', NULL, '["\\((2, -3)\\)", "\\((-3, 2)\\)", "\\((4, 9)\\)", "\\((3, -2)\\)"]', 3, NULL, 1, 'mcq', 'ប្រៀបធៀបនឹងទម្រង់ \(\frac{(x - h)^2}{a^2} - \frac{(y - k)^2}{b^2} = 1\) បាន \(h = 3, k = -2\) ដូច្នេះផ្ចិតគឺ \((3, -2)\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'easy', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22704, 'ចំពោះគ្រប់អ៊ីពែបូល តើអ៊ុចសង់ទ្រីស៊ីតេ \(e = \frac{c}{a}\) ផ្ទៀងផ្ទាត់លក្ខខណ្ឌណា?', NULL, '["\\(e > 1\\)", "\\(0 < e < 1\\)", "\\(e < 0\\)", "\\(e = 1\\)"]', 0, NULL, 1, 'mcq', 'ព្រោះកំណុំស្ថិតនៅខាងក្រៅកំពូល (\(c > a > 0\)) នោះ \(e = \frac{c}{a} > 1\) ជានិច្ច ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអ៊ីពែបូល', 'easy', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22705, 'អ៊ីពែបូល \(\frac{x^2}{9} - \frac{y^2}{16} = 1\) មានតម្លៃ \(c\) (ចម្ងាយពីផ្ចិតទៅកំណុំ) ស្មើប៉ុន្មាន?', NULL, '["\\(\\sqrt{7}\\)", "\\(7\\)", "\\(5\\)", "\\(25\\)"]', 2, NULL, 1, 'mcq', 'គេមាន \(a^2 = 9, b^2 = 16 \implies c^2 = a^2 + b^2 = 9 + 16 = 25 \implies c = 5\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22706, 'សមីការដឺក្រេទី 2 \(Ax^2 + By^2 + Cx + Dy + E = 0\) តាងឱ្យអ៊ីពែបូល កាលណា \(A\) និង \(B\) ផ្ទៀងផ្ទាត់៖', NULL, '["\\(AB < 0\\)", "\\(AB = 0\\)", "\\(AB > 0\\)", "\\(A = B\\)"]', 0, NULL, 1, 'mcq', 'សមីការទូទៅតាងឱ្យអ៊ីពែបូល កាលណា \(A\) និង \(B\) មានសញ្ញាផ្ទុយគ្នា គឺ \(AB < 0\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'easy', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22707, 'អ៊ីពែបូល \(9x^2 - 16y^2 = 144\) មានអ៊ុចសង់ទ្រីស៊ីតេ \(e\) ស្មើប៉ុន្មាន?', NULL, '["\\(\\frac{5}{3}\\)", "\\(\\frac{3}{4}\\)", "\\(\\frac{5}{4}\\)", "\\(\\frac{4}{5}\\)"]', 2, NULL, 1, 'mcq', 'ចែកនឹង \(144\) បាន \(\frac{x^2}{16} - \frac{y^2}{9} = 1\) នោះ \(a = 4, b = 3, c = 5\) ដូច្នេះ \(e = \frac{c}{a} = \frac{5}{4}\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអ៊ីពែបូល', 'easy', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22708, 'តើកំពូលទាំងពីរនៃអ៊ីពែបូល \(\frac{y^2}{16} - \frac{x^2}{9} = 1\) គឺជាចំណុចណា?', NULL, '["\\((0, \\pm 3)\\)", "\\((0, \\pm 4)\\)", "\\((\\pm 4, 0)\\)", "\\((\\pm 5, 0)\\)"]', 1, NULL, 1, 'mcq', 'ដោយអ័ក្សទទឹងនៅលើអ័ក្សអរដោនេ និង \(a^2 = 16 \implies a = 4\) នោះកំពូលគឺ \((0, \pm 4)\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22709, 'តើសមីការអាស៊ីមតូតនៃអ៊ីពែបូល \(\frac{x^2}{16} - \frac{y^2}{9} = 1\) គឺជាមួយណា?', NULL, '["\\(y = \\pm \\frac{16}{9}x\\)", "\\(y = \\pm \\frac{9}{16}x\\)", "\\(y = \\pm \\frac{4}{3}x\\)", "\\(y = \\pm \\frac{3}{4}x\\)"]', 3, NULL, 1, 'mcq', 'គេមាន \(a = 4, b = 3\) នោះសមីការអាស៊ីមតូតគឺ \(y = \pm \frac{b}{a}x = \pm \frac{3}{4}x\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22710, 'តើកំណុំទាំងពីរនៃអ៊ីពែបូល \(\frac{x^2}{4} - \frac{y^2}{12} = 1\) គឺជាចំណុចណា?', NULL, '["\\((0, \\pm 4)\\)", "\\((\\pm 4, 0)\\)", "\\((\\pm 2, 0)\\)", "\\((\\pm \\sqrt{8}, 0)\\)"]', 1, NULL, 1, 'mcq', 'គេមាន \(a^2 = 4, b^2 = 12 \implies c^2 = 4 + 12 = 16 \implies c = 4\) ដូច្នេះកំណុំគឺ \((\pm 4, 0)\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'easy', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22711, 'កំណត់កូអរដោនេកំណុំនៃអ៊ីពែបូល \(4x^2 - 9y^2 = -36\) ។', NULL, '["\\((\\pm \\sqrt{13}, 0)\\)", "\\((0, \\pm \\sqrt{5})\\)", "\\((0, \\pm \\sqrt{13})\\)", "\\((\\pm 3, 0)\\)"]', 2, NULL, 2, 'mcq', 'ចែកនឹង \(-36\) បាន \(\frac{y^2}{4} - \frac{x^2}{9} = 1\) មានអ័ក្សទទឹងលើ \(Oy\) ដោយ \(a^2 = 4, b^2 = 9 \implies c = \sqrt{13}\) ដូច្នេះកំណុំគឺ \((0, \pm \sqrt{13})\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'medium', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22712, 'រកកូអរដោនេកំណុំនៃអ៊ីពែបូល \(16(y - 2)^2 - 9(x + 2)^2 = 144\) ។', NULL, '["\\((-2, 7)\\text{ និង }(-2, -3)\\)", "\\((3, 2)\\text{ និង }(-7, 2)\\)", "\\((-2, 5)\\text{ និង }(-2, -1)\\)", "\\((2, 7)\\text{ និង }(2, -3)\\)"]', 0, NULL, 2, 'mcq', 'សមីការស្ដង់ដាគឺ \(\frac{(y - 2)^2}{9} - \frac{(x + 2)^2}{16} = 1\) មានផ្ចិត \(I(-2, 2)\), \(c = \sqrt{9 + 16} = 5\) ដូច្នេះកំណុំគឺ \((-2, 2 \pm 5)\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'medium', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22713, 'រកអ៊ុចសង់ទ្រីស៊ីតេនៃអ៊ីពែបូល \(4(x - 2)^2 - 9(y + 3)^2 = 36\) ។', NULL, '["\\(\\frac{5}{3}\\)", "\\(\\frac{\\sqrt{13}}{3}\\)", "\\(\\frac{\\sqrt{13}}{2}\\)", "\\(\\frac{\\sqrt{5}}{3}\\)"]', 1, NULL, 2, 'mcq', 'សមីការស្ដង់ដាគឺ \(\frac{(x - 2)^2}{9} - \frac{(y + 3)^2}{4} = 1\) មាន \(a = 3, b = 2, c = \sqrt{13}\) ដូច្នេះ \(e = \frac{\sqrt{13}}{3}\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអ៊ីពែបូល', 'medium', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22714, 'តើសមីការអាស៊ីមតូតនៃអ៊ីពែបូល \(\frac{y^2}{16} - \frac{x^2}{9} = 1\) គឺជាមួយណា?', NULL, '["\\(y = \\pm \\frac{16}{9}x\\)", "\\(y = \\pm \\frac{3}{4}x\\)", "\\(y = \\pm \\frac{4}{3}x\\)", "\\(y = \\pm 4x\\)"]', 2, NULL, 2, 'mcq', 'អ័ក្សទទឹងលើ \(Oy\) មាន \(a = 4, b = 3\) ដូច្នេះអាស៊ីមតូតគឺ \(y = \pm \frac{a}{b}x = \pm \frac{4}{3}x\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'medium', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22715, 'រកផ្ចិតនៃអ៊ីពែបូល \(9x^2 - y^2 - 36x - 6y + 18 = 0\) ។', NULL, '["\\((2, -3)\\)", "\\((-4, -3)\\)", "\\((2, 3)\\)", "\\((-2, 3)\\)"]', 0, NULL, 2, 'mcq', 'បំពេញការ៉េបាន \(9(x - 2)^2 - (y + 3)^2 = 9 \iff (x - 2)^2 - \frac{(y + 3)^2}{9} = 1\) ដូច្នេះផ្ចិតគឺ \((2, -3)\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'medium', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22716, 'រកសមីការស្ដង់ដានៃអ៊ីពែបូលដែលមានកំពូល \((\pm 1, 0)\) និងអាស៊ីមតូត \(y = \pm 3x\) ។', NULL, '["\\(x^2 - \\frac{y^2}{3} = 1\\)", "\\(\\frac{x^2}{9} - y^2 = 1\\)", "\\(y^2 - \\frac{x^2}{9} = 1\\)", "\\(x^2 - \\frac{y^2}{9} = 1\\)"]', 3, NULL, 2, 'mcq', 'កំពូល \((\pm 1, 0)\) ឱ្យ \(a = 1\) និង \(\frac{b}{a} = 3 \implies b = 3\) ដូច្នេះ \(x^2 - \frac{y^2}{9} = 1\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'medium', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22717, 'រកកំណុំទាំងពីរនៃអ៊ីពែបូល \(-x^2 + 4y^2 - 2x - 16y + 11 = 0\) ។', NULL, '["\\((-1, 2 \\pm \\sqrt{5})\\)", "\\((1, -2 \\pm \\sqrt{5})\\)", "\\((-1, 2 \\pm \\sqrt{3})\\)", "\\((-1 \\pm \\sqrt{5}, 2)\\)"]', 0, NULL, 2, 'mcq', 'បំពេញការ៉េបាន \(4(y - 2)^2 - (x + 1)^2 = 4 \iff (y - 2)^2 - \frac{(x + 1)^2}{4} = 1\) មាន \(I(-1, 2), a = 1, b = 2, c = \sqrt{5}\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'medium', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22718, 'រកសមីការស្ដង់ដានៃអ៊ីពែបូលដែលមានកំពូល \((0, \pm 3)\) និងអាស៊ីមតូត \(y = \pm 3x\) ។', NULL, '["\\(y^2 - \\frac{x^2}{9} = 1\\)", "\\(\\frac{y^2}{9} - x^2 = 1\\)", "\\(\\frac{y^2}{9} - \\frac{x^2}{9} = 1\\)", "\\(\\frac{x^2}{9} - y^2 = 1\\)"]', 1, NULL, 2, 'mcq', 'កំពូល \((0, \pm 3)\) ឱ្យ \(a = 3\) និង \(\frac{a}{b} = 3 \implies b = 1\) ដូច្នេះ \(\frac{y^2}{9} - x^2 = 1\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'medium', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22719, 'រកសមីការអាស៊ីមតូតនៃអ៊ីពែបូល \(\frac{(y - 1)^2}{4} - \frac{(x + 4)^2}{9} = 1\) ។', NULL, '["\\(y = \\frac{2}{3}x - \\frac{5}{3}\\text{ និង }y = -\\frac{2}{3}x + \\frac{11}{3}\\)", "\\(y = \\frac{3}{2}x + 7\\text{ និង }y = -\\frac{3}{2}x - 5\\)", "\\(y = \\frac{2}{3}x + 1\\text{ និង }y = -\\frac{2}{3}x + 1\\)", "\\(y = \\frac{2}{3}x + \\frac{11}{3}\\text{ និង }y = -\\frac{2}{3}x - \\frac{5}{3}\\)"]', 3, NULL, 2, 'mcq', 'អាស៊ីមតូតគឺ \(y = 1 \pm \frac{2}{3}(x + 4)\) ដែលផ្ដល់ \(y = \frac{2}{3}x + \frac{11}{3}\) និង \(y = -\frac{2}{3}x - \frac{5}{3}\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'medium', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22720, 'រកសមីការអ៊ីពែបូលដែលមានកំណុំ \((\pm 4, 0)\) និងផលដកចម្ងាយពីចំណុចលើអ៊ីពែបូលទៅកំណុំទាំងពីរស្មើនឹង \(4\) ។', NULL, '["\\(\\frac{x^2}{16} - \\frac{y^2}{4} = 1\\)", "\\(\\frac{y^2}{4} - \\frac{x^2}{12} = 1\\)", "\\(\\frac{x^2}{4} - \\frac{y^2}{12} = 1\\)", "\\(\\frac{x^2}{12} - \\frac{y^2}{4} = 1\\)"]', 2, NULL, 2, 'mcq', 'គេមាន \(c = 4, 2a = 4 \implies a = 2\) និង \(b^2 = c^2 - a^2 = 16 - 4 = 12\) ដូច្នេះ \(\frac{x^2}{4} - \frac{y^2}{12} = 1\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'medium', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22721, 'សមីការ \(3x^2 - 2y^2 + 24x + 12y + 24 = 0\) មានទម្រង់ស្ដង់ដាដូចម្តេច?', NULL, '["\\(\\frac{(x + 4)^2}{2} + \\frac{(y - 3)^2}{3} = 1\\)", "\\(\\frac{(y - 3)^2}{3} - \\frac{(x + 4)^2}{2} = 1\\)", "\\(\\frac{(x + 4)^2}{2} - \\frac{(y - 3)^2}{3} = 1\\)", "\\(\\frac{(x - 4)^2}{2} - \\frac{(y + 3)^2}{3} = 1\\)"]', 2, NULL, 2, 'mcq', 'បំពេញការ៉េបាន \(3(x + 4)^2 - 2(y - 3)^2 = 6 \iff \frac{(x + 4)^2}{2} - \frac{(y - 3)^2}{3} = 1\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'medium', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22722, 'តើប្រវែងអង្កត់កាត់កំណុំកែងអ័ក្សទទឹងនៃអ៊ីពែបូល \(\frac{x^2}{16} - \frac{y^2}{9} = 1\) ស្មើប៉ុន្មាន?', NULL, '["\\(6\\)", "\\(\\frac{9}{2}\\)", "\\(8\\)", "\\(\\frac{32}{3}\\)"]', 1, NULL, 2, 'mcq', 'ប្រវែងអង្កត់កាត់កំណុំកែងអ័ក្សទទឹងគឺ \(\frac{2b^2}{a} = \frac{2 \times 9}{4} = \frac{9}{2}\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'medium', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22723, 'រកសមីការស្ដង់ដានៃអ៊ីពែបូលដែលគ្រប់ចំណុចលើវាមានផលដកចម្ងាយពី \((2, 2)\) និង \((10, 2)\) ស្មើនឹង \(6\) ។', NULL, '["\\(\\frac{(x - 6)^2}{16} - \\frac{(y - 2)^2}{9} = 1\\)", "\\(\\frac{(x - 6)^2}{7} - \\frac{(y - 2)^2}{9} = 1\\)", "\\(\\frac{(y - 2)^2}{9} - \\frac{(x - 6)^2}{7} = 1\\)", "\\(\\frac{(x - 6)^2}{9} - \\frac{(y - 2)^2}{7} = 1\\)"]', 3, NULL, 2, 'mcq', 'ផ្ចិតគឺ \((6, 2)\), \(c = 4, a = 3 \implies b^2 = 16 - 9 = 7\) ដូច្នេះ \(\frac{(x - 6)^2}{9} - \frac{(y - 2)^2}{7} = 1\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'medium', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22724, 'អ៊ីពែបូលមួយមានកំពូល \((\pm 3, 0)\) និងកាត់តាមចំណុច \((5, 2)\) ។ រកសមីការស្ដង់ដានៃអ៊ីពែបូលនេះ ។', NULL, '["\\(\\frac{y^2}{9} - \\frac{4x^2}{9} = 1\\)", "\\(\\frac{x^2}{9} - \\frac{9y^2}{4} = 1\\)", "\\(\\frac{x^2}{9} - \\frac{y^2}{4} = 1\\)", "\\(\\frac{x^2}{9} - \\frac{4y^2}{9} = 1\\)"]', 3, NULL, 2, 'mcq', 'ជំនួស \(a = 3\) និង \((5, 2)\) ក្នុង \(\frac{x^2}{9} - \frac{y^2}{b^2} = 1\) បាន \(b^2 = \frac{9}{4}\) ដូច្នេះ \(\frac{x^2}{9} - \frac{4y^2}{9} = 1\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'medium', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22725, 'រកសមីការបន្ទាត់ប៉ះទៅនឹងអ៊ីពែបូល \(\frac{x^2}{4} - \frac{y^2}{9} = 1\) ត្រង់ចំណុច \((4, 3\sqrt{3})\) ។', NULL, '["\\(4x - 3\\sqrt{3}y = 1\\)", "\\(x - \\sqrt{3}y = 1\\)", "\\(x - \\frac{\\sqrt{3}}{3}y = 1\\)", "\\(x + \\frac{\\sqrt{3}}{3}y = 1\\)"]', 2, NULL, 3, 'mcq', 'ប្រើរូបមន្ត \(\frac{x_0 x}{a^2} - \frac{y_0 y}{b^2} = 1\) បាន \(\frac{4x}{4} - \frac{3\sqrt{3}y}{9} = 1 \iff x - \frac{\sqrt{3}}{3}y = 1\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'hard', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22726, 'រកសមីការអ៊ីពែបូលដែលមានកំណុំ \((0, 0)\) និង \((8, 0)\) ហើយអាស៊ីមតូតទាំងពីរមានសមីការ \(y = \pm 2(x - 4)\) ។', NULL, '["\\(\\frac{y^2}{\\frac{64}{5}} - \\frac{(x - 4)^2}{\\frac{16}{5}} = 1\\)", "\\(\\frac{(x - 4)^2}{16} - \\frac{y^2}{64} = 1\\)", "\\(\\frac{(x - 4)^2}{\\frac{64}{5}} - \\frac{y^2}{\\frac{16}{5}} = 1\\)", "\\(\\frac{(x - 4)^2}{\\frac{16}{5}} - \\frac{y^2}{\\frac{64}{5}} = 1\\)"]', 3, NULL, 3, 'mcq', 'ផ្ចិត \((4, 0), c = 4\) និង \(\frac{b}{a} = 2 \implies a^2 + 4a^2 = 16 \implies a^2 = \frac{16}{5}, b^2 = \frac{64}{5}\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'hard', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22727, 'អ៊ីពែបូលស្មើ (ដែលមានអាស៊ីមតូតកែងគ្នា \(a = b\)) មានអ៊ុចសង់ទ្រីស៊ីតេស្មើប៉ុន្មាន?', NULL, '["\\(\\sqrt{2}\\)", "\\(\\sqrt{3}\\)", "\\(2\\)", "\\(\\frac{\\sqrt{2}}{2}\\)"]', 0, NULL, 3, 'mcq', 'ដោយ \(a = b\) នោះ \(c = \sqrt{a^2 + a^2} = a\sqrt{2}\) ដូច្នេះ \(e = \frac{c}{a} = \sqrt{2}\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអ៊ីពែបូល', 'hard', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22728, 'រកមេគុណប្រាប់ទិសនៃបន្ទាត់ប៉ះទៅនឹងអ៊ីពែបូល \(9x^2 - 4y^2 = 36\) ដែលកាត់តាមចំណុច \((1, 0)\) ។', NULL, '["\\(\\pm \\frac{\\sqrt{3}}{2}\\)", "\\(\\pm \\sqrt{3}\\)", "\\(\\pm 2\\)", "\\(\\pm \\frac{3}{2}\\)"]', 1, NULL, 3, 'mcq', 'តាងបន្ទាត់ \(y = m(x - 1)\) ជំនួសចូល \(9x^2 - 4y^2 = 36\) ហើយដាក់ \(\Delta = 0\) បាន \(m^2 = 3 \implies m = \pm \sqrt{3}\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'hard', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22729, 'អ៊ីពែបូល \(\frac{x^2}{a^2} - \frac{y^2}{b^2} = 1\) មានអាស៊ីមតូតមួយបង្កើតមុំ \(30^\circ\) ជាមួយអ័ក្សទទឹង \(Ox\) ។ រកអ៊ុចសង់ទ្រីស៊ីតេនៃអ៊ីពែបូល ។', NULL, '["\\(\\frac{\\sqrt{3}}{2}\\)", "\\(\\sqrt{3}\\)", "\\(\\frac{2\\sqrt{3}}{3}\\)", "\\(2\\)"]', 2, NULL, 3, 'mcq', 'គេមាន \(\frac{b}{a} = \tan 30^\circ = \frac{1}{\sqrt{3}}\) ដូច្នេះ \(e = \sqrt{1 + \frac{b^2}{a^2}} = \sqrt{1 + \frac{1}{3}} = \frac{2\sqrt{3}}{3}\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអ៊ីពែបូល', 'hard', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22730, 'អ៊ីពែបូល \(\frac{x^2}{a^2} - \frac{y^2}{b^2} = 1\) ប៉ះនឹងបន្ទាត់ \(2x - y - 4 = 0\) ។ បើ \(b = 2\) តើ \(a\) ស្មើប៉ុន្មាន?', NULL, '["\\(4\\)", "\\(\\sqrt{5}\\)", "\\(2\\)", "\\(\\sqrt{3}\\)"]', 1, NULL, 3, 'mcq', 'ជំនួស \(y = 2x - 4\) រួចដាក់ \(\Delta = 0\) បាន \(4a^2 - b^2 = 16\) ។ បើ \(b = 2\) បាន \(4a^2 = 20 \implies a = \sqrt{5}\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'hard', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22731, 'តើតម្លៃ \(k\) ណាខ្លះដែលធ្វើឱ្យសមីការ \(\frac{x^2}{k - 1} + \frac{y^2}{k - 5} = 1\) តាងឱ្យអ៊ីពែបូល?', NULL, '["\\(1 < k < 5\\)", "\\(k < 1\\)", "\\(k > 1\\)", "\\(k > 5\\)"]', 0, NULL, 3, 'mcq', 'ដើម្បីជាអ៊ីពែបូល ភាគបែងទាំងពីរត្រូវមានសញ្ញាផ្ទុយគ្នា គឺ \((k - 1)(k - 5) < 0 \iff 1 < k < 5\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'hard', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Evaluate');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-b23366d2cb.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22732, 'ស្ថានីយវិទ្យុឆ្នេរសមុទ្រពីរគឺ \(A(-160, 0)\) និង \(B(160, 0)\) (ឯកតាជា \(\text{km}\)) ។ កប៉ាល់ \(P\) នៅចម្ងាយ \(160\text{ km}\) ពីឆ្នេរ (\(y = 160\)) ហើយនៅជិត \(B\) ជាង \(A\) ចម្ងាយ \(256\text{ km}\) ។ រកសមីការគន្លងអ៊ីពែបូលរបស់កប៉ាល់ ។', 'g12sc-b23366d2cb.svg', '["\\(\\frac{x^2}{160^2} - \\frac{y^2}{128^2} = 1\\)", "\\(\\frac{x^2}{128^2} - \\frac{y^2}{96^2} = 1\\)", "\\(\\frac{y^2}{128^2} - \\frac{x^2}{96^2} = 1\\)", "\\(\\frac{x^2}{256^2} - \\frac{y^2}{160^2} = 1\\)"]', 1, NULL, 3, 'mcq', 'គេមាន \(2a = 256 \implies a = 128\) និង \(c = 160 \implies b = \sqrt{160^2 - 128^2} = 96\) ដូច្នេះ \(\frac{x^2}{128^2} - \frac{y^2}{96^2} = 1\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអ៊ីពែបូល', 'pisa', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-356110aa5e.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22733, 'ភាគល្អិតអាល់ហ្វាត្រូវបានច្រានចេញពីណ្វៃយ៉ូត្រង់គល់ \(O(0, 0)\) តាមគន្លងអ៊ីពែបូលដែលមានអាស៊ីមតូត \(y = \pm \frac{1}{2}x\) និងកំពូលនៅ \(V(3, 0)\) ។ រកសមីការនៃគន្លងនេះ ។', 'g12sc-356110aa5e.svg', '["\\(\\frac{x^2}{9} - \\frac{4y^2}{9} = 1\\; (x \\ge 3)\\)", "\\(\\frac{x^2}{9} - \\frac{y^2}{4} = 1\\; (x \\ge 3)\\)", "\\(\\frac{y^2}{9} - \\frac{4x^2}{9} = 1\\)", "\\(\\frac{x^2}{9} - \\frac{9y^2}{4} = 1\\; (x \\ge 3)\\)"]', 0, NULL, 3, 'mcq', 'គេមាន \(a = 3\) និង \(\frac{b}{a} = \frac{1}{2} \implies b = \frac{3}{2}\) ដូច្នេះ \(\frac{x^2}{9} - \frac{4y^2}{9} = 1\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'pisa', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-fadfb105ae.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22734, 'ប៉មត្រជាក់នៃរោងចក្រអគ្គិសនីមួយមានមុខកាត់រាងអ៊ីពែបូល \(\frac{x^2}{a^2} - \frac{y^2}{b^2} = 1\) ។ កន្លែងតូចបំផុតត្រង់ \(y = 0\) មានកាំ \(a = 30\text{ m}\) និងនៅកម្ពស់ \(y = 80\text{ m}\) មានកាំ \(x = 50\text{ m}\) ។ រកតម្លៃ \(b\) ។', 'g12sc-fadfb105ae.svg', '["\\(40\\text{ m}\\)", "\\(50\\text{ m}\\)", "\\(60\\text{ m}\\)", "\\(45\\text{ m}\\)"]', 2, NULL, 3, 'mcq', 'ជំនួស \((50, 80)\) ចូល \(\frac{50^2}{30^2} - \frac{80^2}{b^2} = 1 \implies \frac{80^2}{b^2} = \frac{16}{9} \implies b = 60\text{ m}\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'pisa', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-c87b73616f.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22735, 'កញ្ចក់ទីពីរនៃកែវយឺត Cassegrain មានមុខកាត់រាងអ៊ីពែបូលផ្ចិត \(O(0, 0)\) កំណុំ \(F_1(10, 0), F_2(-10, 0)\) និងកំពូល \(V_1(6, 0)\) (គិតជា \(\text{cm}\)) ។ រកអ៊ុចសង់ទ្រីស៊ីតេ និងសមីការអ៊ីពែបូល ។', 'g12sc-c87b73616f.svg', '["\\(e = \\frac{5}{4},\\; \\frac{x^2}{36} - \\frac{y^2}{100} = 1\\)", "\\(e = \\frac{3}{5},\\; \\frac{x^2}{36} - \\frac{y^2}{64} = 1\\)", "\\(e = \\frac{5}{3},\\; \\frac{x^2}{64} - \\frac{y^2}{36} = 1\\)", "\\(e = \\frac{5}{3},\\; \\frac{x^2}{36} - \\frac{y^2}{64} = 1\\)"]', 3, NULL, 3, 'mcq', 'គេមាន \(a = 6, c = 10 \implies b = \sqrt{100 - 36} = 8\) និង \(e = \frac{10}{6} = \frac{5}{3}\) ។', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអ៊ីពែបូល', 'pisa', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-2f768769c5.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22736, 'ផ្កាយដុះកន្ទុយមួយធ្វើដំណើរតាមគន្លងអ៊ីពែបូល \(\frac{x^2}{9} - \frac{y^2}{16} = 1\; (x \ge 3)\) ជុំវិញព្រះអាទិត្យដែលស្ថិតនៅកំណុំ \(F_1(c, 0)\) (ឯកតាជា \(\text{AU}\)) ។ តើចម្ងាយជិតបំផុតពីផ្កាយដុះកន្ទុយទៅព្រះអាទិត្យស្មើប៉ុន្មាន?', 'g12sc-2f768769c5.svg', '["\\(3\\text{ AU}\\)", "\\(8\\text{ AU}\\)", "\\(5\\text{ AU}\\)", "\\(2\\text{ AU}\\)"]', 3, NULL, 3, 'mcq', 'គេមាន \(a = 3, b = 4 \implies c = 5\) ដូច្នេះចម្ងាយជិតបំផុត (ពីកំពូលទៅកំណុំ) គឺ \(c - a = 5 - 3 = 2\text{ AU}\) ។', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'pisa', 1, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22737, 'គេឱ្យសមីការអ៊ីពែបូល \(9x^2 - 16y^2 = 144\) ។ រកសមីការស្ដង់ដា កូអរដោនេផ្ចិត កំពូល កំណុំ និងសមីការអាស៊ីមតូត ។', NULL, '[]', 0, NULL, 5, 'writing', 'ចែកអង្គទាំងពីរនឹង \(144\) បានសមីការស្ដង់ដា \(\frac{x^2}{16} - \frac{y^2}{9} = 1\) (1 ពិន្ទុ)
ទាញបាន \(a = 4, b = 3\) និង \(c = \sqrt{a^2 + b^2} = \sqrt{16 + 9} = 5\) (1 ពិន្ទុ)
ផ្ចិតគឺ \(I(0, 0)\) និងកំពូលទាំងពីរគឺ \(V_1(4, 0), V_2(-4, 0)\) (1 ពិន្ទុ)
កំណុំទាំងពីរគឺ \(F_1(5, 0), F_2(-5, 0)\) (1 ពិន្ទុ)
សមីការអាស៊ីមតូតគឺ \(y = \pm \frac{b}{a}x = \pm \frac{3}{4}x\) ។ (1 ពិន្ទុ)', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'easy', 0, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22738, 'គេឱ្យសមីការអ៊ីពែបូល \(4x^2 - 9y^2 = -36\) ។ រកសមីការស្ដង់ដា កំពូល កំណុំ អ៊ុចសង់ទ្រីស៊ីតេ និងអាស៊ីមតូត ។', NULL, '[]', 0, NULL, 5, 'writing', 'ចែកអង្គទាំងពីរនឹង \(-36\) បានសមីការស្ដង់ដា \(\frac{y^2}{4} - \frac{x^2}{9} = 1\) (1 ពិន្ទុ)
ដោយអ័ក្សទទឹងលើ \(Oy\) បាន \(a = 2, b = 3, c = \sqrt{4 + 9} = \sqrt{13}\) (1 ពិន្ទុ)
កំពូលទាំងពីរគឺ \(V_1(0, 2), V_2(0, -2)\) និងកំណុំគឺ \(F_1(0, \sqrt{13}), F_2(0, -\sqrt{13})\) (1 ពិន្ទុ)
អ៊ុចសង់ទ្រីស៊ីតេគឺ \(e = \frac{c}{a} = \frac{\sqrt{13}}{2}\) (1 ពិន្ទុ)
សមីការអាស៊ីមតូតគឺ \(y = \pm \frac{a}{b}x = \pm \frac{2}{3}x\) ។ (1 ពិន្ទុ)', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'medium', 0, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22739, 'រកសមីការស្ដង់ដានៃអ៊ីពែបូលដែលមានកំពូល \((3, -5)\) និង \((3, 1)\) ហើយអាស៊ីមតូតមានសមីការ \(y = 2x - 8\) និង \(y = -2x + 4\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ដោយកំពូលមាន \(x = 3\) ដូចគ្នា នោះអ័ក្សទទឹងស្រប \(Oy\) និងផ្ចិតគឺ \(I\left(3, \frac{-5 + 1}{2}\right) = I(3, -2)\) (1 ពិន្ទុ)
រក \(a = |1 - (-2)| = 3 \implies a^2 = 9\) (1 ពិន្ទុ)
ពីមេគុណប្រាប់ទិសអាស៊ីមតូតបាន \(\frac{a}{b} = 2 \implies b = \frac{3}{2} \implies b^2 = \frac{9}{4}\) (1 ពិន្ទុ)
គណនា \(c = \sqrt{9 + \frac{9}{4}} = \frac{3\sqrt{5}}{2}\) (1 ពិន្ទុ)
សមីការស្ដង់ដាគឺ \(\frac{(y + 2)^2}{9} - \frac{4(x - 3)^2}{9} = 1\) ។ (1 ពិន្ទុ)', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'medium', 0, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22740, 'បំប្លែងសមីការ \(25x^2 - 16y^2 + 250x + 32y + 209 = 0\) ជាសមីការស្ដង់ដា រួចរកផ្ចិត កំពូល កំណុំ និងអាស៊ីមតូត ។', NULL, '[]', 0, NULL, 5, 'writing', 'ផ្ដុំតួបាន \(25(x^2 + 10x + 25) - 16(y^2 - 2y + 1) = -209 + 625 - 16 = 400\) (1 ពិន្ទុ)
ចែកនឹង \(400\) បាន \(\frac{(x + 5)^2}{16} - \frac{(y - 1)^2}{25} = 1\) (1 ពិន្ទុ)
ផ្ចិត \(I(-5, 1)\) និង \(a = 4, b = 5, c = \sqrt{41}\) (1 ពិន្ទុ)
កំពូល \(V_1(-9, 1), V_2(-1, 1)\) និងកំណុំ \(F(-5 \pm \sqrt{41}, 1)\) (1 ពិន្ទុ)
សមីការអាស៊ីមតូតគឺ \(y = 1 \pm \frac{5}{4}(x + 5)\) ។ (1 ពិន្ទុ)', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'medium', 0, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22741, 'រកសមីការស្ដង់ដានៃអ៊ីពែបូលដែលមានកំណុំ \((7, 1)\) និង \((-3, 1)\) ហើយអាស៊ីមតូតមានសមីការ \(y = \frac{3}{4}x - \frac{1}{2}\) និង \(y = -\frac{3}{4}x + \frac{5}{2}\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ផ្ចិតជាចំណុចកណ្ដាលនៃកំណុំទាំងពីរគឺ \(I\left(\frac{7 - 3}{2}, 1\right) = I(2, 1)\) និង \(c = 5\) (1 ពិន្ទុ)
អ័ក្សទទឹងស្រប \(Ox\) និងពីអាស៊ីមតូតបាន \(\frac{b}{a} = \frac{3}{4} \implies b = \frac{3}{4}a\) (1 ពិន្ទុ)
ជំនួសក្នុង \(a^2 + b^2 = c^2 \implies a^2 + \frac{9}{16}a^2 = 25 \implies \frac{25}{16}a^2 = 25 \implies a = 4\) (1 ពិន្ទុ)
ទាញបាន \(b = \frac{3}{4}(4) = 3\) (1 ពិន្ទុ)
សមីការស្ដង់ដាគឺ \(\frac{(x - 2)^2}{16} - \frac{(y - 1)^2}{9} = 1\) ។ (1 ពិន្ទុ)', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'medium', 0, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22742, 'បំប្លែងសមីការ \(4x^2 - 9y^2 + 32x + 18y + 91 = 0\) ជាសមីការស្ដង់ដា រួចរកផ្ចិត កំពូល កំណុំ និងអាស៊ីមតូត ។', NULL, '[]', 0, NULL, 5, 'writing', 'ផ្ដុំតួបាន \(4(x + 4)^2 - 9(y - 1)^2 = -91 + 64 - 9 = -36\) (1 ពិន្ទុ)
ចែកនឹង \(-36\) បាន \(\frac{(y - 1)^2}{4} - \frac{(x + 4)^2}{9} = 1\) (1 ពិន្ទុ)
ផ្ចិត \(I(-4, 1)\), \(a = 2, b = 3, c = \sqrt{13}\) (1 ពិន្ទុ)
កំពូល \(V_1(-4, 3), V_2(-4, -1)\) និងកំណុំ \(F(-4, 1 \pm \sqrt{13})\) (1 ពិន្ទុ)
សមីការអាស៊ីមតូតគឺ \(y = 1 \pm \frac{2}{3}(x + 4)\) ។ (1 ពិន្ទុ)', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'hard', 0, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22743, 'រកសមីការបន្ទាត់ប៉ះទាំងអស់ទៅនឹងអ៊ីពែបូល \(9x^2 - 4y^2 = 36\) ដែលកាត់តាមចំណុច \((1, 0)\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'បន្ទាត់កាត់តាម \((1, 0)\) មិនឈរមានសមីការ \(y = m(x - 1)\) (1 ពិន្ទុ)
ជំនួសក្នុង \(9x^2 - 4y^2 = 36\) បាន \((9 - 4m^2)x^2 + 8m^2 x - (4m^2 + 36) = 0\) (1 ពិន្ទុ)
លក្ខខណ្ឌប៉ះ \(\Delta'' = 16m^4 + (9 - 4m^2)(4m^2 + 36) = 0\) (1 ពិន្ទុ)
ពន្លាតនិងសម្រួលបាន \(-108m^2 + 324 = 0 \implies m^2 = 3 \implies m = \pm \sqrt{3}\) (1 ពិន្ទុ)
ដូច្នេះបន្ទាត់ប៉ះទាំងពីរគឺ \(y = \sqrt{3}(x - 1)\) និង \(y = -\sqrt{3}(x - 1)\) ។ (1 ពិន្ទុ)', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'hard', 0, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22744, 'កំណុំទាំងពីរនៃអ៊ីពែបូលគឺ \(F_1(0, 3)\) និង \(F_2(0, -3)\) ។ ប្រើនិយមន័យដើម្បីទាញរកសមីការស្ដង់ដា បើផលដកចម្ងាយពីចំណុចលើអ៊ីពែបូលទៅ \(F_1\) និង \(F_2\) ស្មើនឹង \(2\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង \(P(x, y)\) លើអ៊ីពែបូល បាន \(\sqrt{x^2 + (y - 3)^2} - \sqrt{x^2 + (y + 3)^2} = \pm 2\) (1 ពិន្ទុ)
លើកអង្គទាំងពីរជាការ៉េហើយសម្រួលបាន \(-3y - 1 = \pm \sqrt{x^2 + (y + 3)^2}\) (1 ពិន្ទុ)
លើកជាការ៉េម្ដងទៀតបាន \(9y^2 + 6y + 1 = x^2 + y^2 + 6y + 9\) (1 ពិន្ទុ)
សម្រួលបាន \(8y^2 - x^2 = 8\) (1 ពិន្ទុ)
ចែកនឹង \(8\) បានសមីការស្ដង់ដា \(y^2 - \frac{x^2}{8} = 1\) ។ (1 ពិន្ទុ)', 'និយមន័យអ៊ីពែបូល', 'hard', 0, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Create');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22745, 'រកសមីការស្ដង់ដានៃអ៊ីពែបូលដែលគ្រប់ចំណុចលើវាមានផលដកចម្ងាយពី \((-3, 0)\) និង \((-3, -3)\) ស្មើនឹង \(2\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណុំមាន \(x = -3\) ដូចគ្នា នោះអ័ក្សទទឹងស្រប \(Oy\) និងផ្ចិត \(I\left(-3, -\frac{3}{2}\right)\) (1 ពិន្ទុ)
ចម្ងាយពីផ្ចិតទៅកំណុំ \(c = \frac{3}{2}\) និង \(2a = 2 \implies a = 1\) (1 ពិន្ទុ)
គណនា \(b^2 = c^2 - a^2 = \frac{9}{4} - 1 = \frac{5}{4}\) (1 ពិន្ទុ)
សរសេរទម្រង់ស្ដង់ដាសម្រាប់អ័ក្សទទឹងឈរ \(\frac{(y - k)^2}{a^2} - \frac{(x - h)^2}{b^2} = 1\) (1 ពិន្ទុ)
ដូច្នេះសមីការស្ដង់ដាគឺ \(\left(y + \frac{3}{2}\right)^2 - \frac{4(x + 3)^2}{5} = 1\) ។ (1 ពិន្ទុ)', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'hard', 0, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-75c2434029.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22746, 'ស្ថានីយចាប់សញ្ញាពីរនៅលើឆ្នេរត្រង់គឺ \(A(-15, 0)\) និង \(B(15, 0)\) (ឯកតាជា \(\text{km}\)) ។ ទូកមួយនៅ \(P(x, 16)\) (\(x > 0\)) នៅជិត \(B\) ជាង \(A\) ចម្ងាយ \(18\text{ km}\) ។ រកសមីការអ៊ីពែបូល និងកូអរដោនេ \(x\) របស់ទូក ។', 'g12sc-75c2434029.svg', '[]', 0, NULL, 5, 'writing', 'ផ្ចិតនៅ \(O(0, 0)\), \(c = 15\) និង \(2a = 18 \implies a = 9\text{ km}\) (1 ពិន្ទុ)
គណនា \(b^2 = c^2 - a^2 = 15^2 - 9^2 = 144 \implies b = 12\text{ km}\) (1 ពិន្ទុ)
សមីការអ៊ីពែបូលគឺ \(\frac{x^2}{81} - \frac{y^2}{144} = 1\) (1 ពិន្ទុ)
ជំនួស \(y = 16\) បាន \(\frac{x^2}{81} = 1 + \frac{256}{144} = \frac{25}{9}\) (1 ពិន្ទុ)
ដោយ \(x > 0\) ទាញបាន \(x = 9 \times \frac{5}{3} = 15\text{ km}\) ។ (1 ពិន្ទុ)', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអ៊ីពែបូល', 'pisa', 0, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-05fcd3b9f9.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22747, 'ប៉មសំណង់មួយមានមុខកាត់រាងអ៊ីពែបូលផ្ចិត \(I(0, 20)\) និងអ័ក្សទទឹងស្រប \(Ox\) ។ កន្លែងរួមតូចបំផុតត្រង់ \(y = 20\) មានកាំ \(15\text{ m}\) និងនៅកំពូល \(y = 40\) មានកាំ \(25\text{ m}\) ។ រកសមីការអ៊ីពែបូល និងអ៊ុចសង់ទ្រីស៊ីតេ ។', 'g12sc-05fcd3b9f9.svg', '[]', 0, NULL, 5, 'writing', 'សមីការមានទម្រង់ \(\frac{x^2}{a^2} - \frac{(y - 20)^2}{b^2} = 1\) ដោយ \(a = 15\) (1 ពិន្ទុ)
ជំនួស \((25, 40)\) បាន \(\frac{25^2}{15^2} - \frac{20^2}{b^2} = 1\) (1 ពិន្ទុ)
គណនា \(\frac{400}{b^2} = \frac{25}{9} - 1 = \frac{16}{9} \implies b^2 = 225 \implies b = 15\) (1 ពិន្ទុ)
សមីការអ៊ីពែបូលគឺ \(\frac{x^2}{225} - \frac{(y - 20)^2}{225} = 1\) (1 ពិន្ទុ)
ដោយ \(a = b = 15\) បាន \(e = \frac{\sqrt{a^2 + b^2}}{a} = \sqrt{2}\) ។ (1 ពិន្ទុ)', 'សមីការអ៊ីពែបូលដែលមានផ្ចិត I(h, k)', 'pisa', 0, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-1807cda99b.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22748, 'ស្ថានីយរ៉ាដាពីរស្ថិតនៅ \(F_1(0, 13)\) និង \(F_2(0, -13)\) (ឯកតាជា \(\text{km}\)) ។ ប្រភពសញ្ញាមួយស្ថិតនៅលើអ៊ីពែបូលដែលមានផលដកចម្ងាយពី \(F_1\) និង \(F_2\) ស្មើនឹង \(10\text{ km}\) ។ រកសមីការអ៊ីពែបូល អាស៊ីមតូត និងអ៊ុចសង់ទ្រីស៊ីតេ ។', 'g12sc-1807cda99b.svg', '[]', 0, NULL, 5, 'writing', 'ផ្ចិតនៅ \(O(0, 0)\), អ័ក្សទទឹងលើ \(Oy\), \(c = 13\) និង \(2a = 10 \implies a = 5\) (1 ពិន្ទុ)
គណនា \(b^2 = c^2 - a^2 = 169 - 25 = 144 \implies b = 12\) (1 ពិន្ទុ)
សមីការស្ដង់ដាគឺ \(\frac{y^2}{25} - \frac{x^2}{144} = 1\) (1 ពិន្ទុ)
សមីការអាស៊ីមតូតគឺ \(y = \pm \frac{a}{b}x = \pm \frac{5}{12}x\) (1 ពិន្ទុ)
អ៊ុចសង់ទ្រីស៊ីតេគឺ \(e = \frac{13}{5} = 2.6\) ។ (1 ពិន្ទុ)', 'អ៊ុចសង់ទ្រីស៊ីតេ និងលក្ខណៈចំណាំងផ្លាតនៃអ៊ីពែបូល', 'pisa', 0, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Apply');
