INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22749, 'កញ្ចក់អ៊ីពែបូលមួយមានសមីការ \(\frac{y^2}{9} - \frac{x^2}{16} = 1\; (y > 0)\) ។ កាំពន្លឺមួយតម្រង់ទៅរកកំណុំ \(F_1\) ហើយប៉ះកញ្ចក់ត្រង់ចំណុច \(P\left(3, \frac{15}{4}\right)\) ។ ក. រកកំណុំទាំងពីរ \(F_1, F_2\) ។ ខ. រកសមីការបន្ទាត់ប៉ះត្រង់ \(P\) ។', 'g12sc-3c6148d1d1.svg', '[]', 0, NULL, 5, 'writing', 'ពីសមីការបាន \(a = 3, b = 4\) នោះ \(c = \sqrt{9 + 16} = 5\) (1 ពិន្ទុ)
កំណុំទាំងពីរគឺ \(F_1(0, 5)\) និង \(F_2(0, -5)\) (1 ពិន្ទុ)
កាំពន្លឺដែលតម្រង់ទៅ \(F_1(0, 5)\) នឹងចាំងផ្លាតត្រឡប់ឆ្ពោះទៅរកកំណុំ \(F_2(0, -5)\) (1 ពិន្ទុ)
ប្រើរូបមន្តបន្ទាត់ប៉ះ \(\frac{y_0 y}{a^2} - \frac{x_0 x}{b^2} = 1\) បាន \(\frac{15y}{4 \times 9} - \frac{3x}{16} = 1\) (1 ពិន្ទុ)
សម្រួលបានសមីការបន្ទាត់ប៉ះ \(\frac{5}{12}y - \frac{3}{16}x = 1\) ឬ \(20y - 9x = 48\) ។ (1 ពិន្ទុ)', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'pisa', 0, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-8be006dc8e.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 22750, 'យានអវកាសមួយហោះកាត់ភពមួយតាមគន្លងអ៊ីពែបូល \(\frac{x^2}{a^2} - \frac{y^2}{b^2} = 1\; (x \ge a)\) ដែលភពស្ថិតនៅកំណុំ \(F_1(c, 0)\) ។ ចម្ងាយជិតបំផុតទៅផ្ចិតភពគឺ \(4 \times 10^3\text{ km}\) និងអ៊ុចសង់ទ្រីស៊ីតេ \(e = \frac{5}{3}\) ។ រកសមីការគន្លង និងប្រវែងអង្កត់កាត់កំណុំកែងអ័ក្សទទឹង ។', 'g12sc-8be006dc8e.svg', '[]', 0, NULL, 5, 'writing', 'តាងឯកតាគិតជា \(10^3\text{ km}\) គេមាន \(c - a = 4\) និង \(\frac{c}{a} = \frac{5}{3} \implies c = \frac{5}{3}a\) (1 ពិន្ទុ)
ជំនួសបាន \(\frac{5}{3}a - a = 4 \implies \frac{2}{3}a = 4 \implies a = 6\) (1 ពិន្ទុ)
ទាញបាន \(c = 10\) និង \(b^2 = c^2 - a^2 = 100 - 36 = 64 \implies b = 8\) (1 ពិន្ទុ)
សមីការគន្លងគឺ \(\frac{x^2}{36} - \frac{y^2}{64} = 1\; (x \ge 6)\) (1 ពិន្ទុ)
ប្រវែងអង្កត់កាត់កំណុំកែងអ័ក្សទទឹងគឺ \(\frac{2b^2}{a} = \frac{2 \times 64}{6} = \frac{64}{3} \times 10^3\text{ km}\) ។ (1 ពិន្ទុ)', 'សមីការអ៊ីពែបូលដែលមានផ្ចិតនៅគល់ O(0, 0)', 'pisa', 0, '12SC', 'អ៊ីពែបូល', 'ជំពូកទី 10 : កោនិក', NULL, 0, 'Create');
